"""Импорт банковских выписок.

Поддерживаются три формата (определяются по заголовку, если формат не задан):

    nova:        date,amount,description
                 2026-03-01,-350.00,Кофейня Зерно
    sfera:       Дата;Номер карты;Сумма;Описание
                 01.03.2026;1234;-350,00;Кофейня Зерно
    sfera_split: Дата;Описание;Приход;Расход
                 01.03.2026;Зарплата;85 000,00;0,00

Кодировка: UTF-8 (с BOM или без), иначе cp1251.
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from dataclasses import dataclass
from decimal import Decimal
from typing import Callable

from ledger.clock import Clock, SystemClock
from ledger.errors import StatementError, StatementRowError, UnknownFormatError, ValidationError
from ledger.models import Transaction, parse_amount
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

_DELIMITERS = (";", ",")
_SFERA_DATE = re.compile(r"\d{2}\.\d{2}\.\d{4}")
# Группы по три цифры строго; пробел или неразрывный пробел (U+00A0) как разделитель тысяч.
_SFERA_AMOUNT = re.compile(r"([+-]?)(\d{1,3}(?:[  ]\d{3})*|\d+)(?:,(\d{1,2}))?")
_ZERO = Decimal("0")


def _nova_row(values: dict[str, str]) -> tuple[dt.date, Decimal, str]:
    try:
        date = dt.date.fromisoformat(values["date"])
    except ValueError as exc:
        raise ValidationError(f"invalid date {values['date']!r}") from exc
    return date, parse_amount(values["amount"]), values["description"]


def _sfera_date(text: str) -> dt.date:
    if not _SFERA_DATE.fullmatch(text):
        raise ValidationError(f"invalid date {text!r}, expected DD.MM.YYYY")
    day, month, year = (int(part) for part in text.split("."))
    try:
        return dt.date(year, month, day)
    except ValueError as exc:
        raise ValidationError(f"invalid date {text!r}") from exc


def _sfera_amount(text: str, *, signed: bool) -> Decimal:
    match = _SFERA_AMOUNT.fullmatch(text.strip())
    if match is None:
        raise ValidationError(f"invalid amount {text!r}")
    sign, whole, frac = match.groups()
    if sign and not signed:
        raise ValidationError(f"sign is not allowed in amount {text!r}")
    digits = whole.replace(" ", "").replace(" ", "")
    return parse_amount(f"{sign}{digits}.{(frac or '00').ljust(2, '0')}")


def _sfera_row(values: dict[str, str]) -> tuple[dt.date, Decimal, str]:
    return (
        _sfera_date(values["дата"]),
        _sfera_amount(values["сумма"], signed=True),
        values["описание"],
    )


def _split_amount(text: str) -> Decimal | None:
    """Сумма из колонки «Приход» или «Расход»; пусто и «0,00» дают None."""
    if not text:
        return None
    amount = _sfera_amount(text, signed=False)
    if amount == _ZERO:
        return None
    return amount


def _sfera_split_row(values: dict[str, str]) -> tuple[dt.date, Decimal, str]:
    income = _split_amount(values["приход"])
    expense = _split_amount(values["расход"])
    if (income is None) == (expense is None):
        raise ValidationError("exactly one of «Приход» and «Расход» must be non-zero")
    amount = income if income is not None else -expense
    return _sfera_date(values["дата"]), amount, values["описание"]


@dataclass(frozen=True)
class _Format:
    name: str
    delimiter: str
    columns: tuple[str, ...]  # нормализованные имена колонок (strip + casefold)
    parse: Callable[[dict[str, str]], tuple[dt.date, Decimal, str]]


_NOVA = _Format("nova", ",", ("date", "amount", "description"), _nova_row)
_SFERA = _Format("sfera", ";", ("дата", "сумма", "описание"), _sfera_row)
_SFERA_SPLIT = _Format(
    "sfera_split", ";", ("дата", "описание", "приход", "расход"), _sfera_split_row
)
_FORMATS: dict[str, _Format] = {f.name: f for f in (_NOVA, _SFERA, _SFERA_SPLIT)}


@dataclass(frozen=True)
class RowError:
    """Строка выписки, которую не удалось импортировать."""

    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    """Итог импорта. added + duplicates + len(errors) — число непропущенных строк данных."""

    format: str
    encoding: str
    added: int
    duplicates: int
    errors: tuple[RowError, ...]


@dataclass(frozen=True)
class _Layout:
    """Формат файла, позиции колонок по имени и строки данных (номер строки, ячейки)."""

    format: _Format
    columns: dict[str, int]
    width: int  # число колонок в заголовке
    rows: list[tuple[int, list[str]]]


def normalize_description(text: str) -> str:
    """Форма описания для сравнения при дедупликации (та же, что у правил категоризации)."""
    return normalize_text(text)


def _read_text(path: str | os.PathLike[str]) -> tuple[str, str]:
    """Возвращает (текст, кодировка): UTF-8 с BOM или без, иначе cp1251."""
    with open(path, "rb") as fh:
        data = fh.read()
    try:
        return data.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return data.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise UnknownFormatError("file is neither UTF-8 nor cp1251") from exc


def _read_records(text: str, delimiter: str) -> list[tuple[int, list[str]]]:
    """Записи CSV с физическим номером строки, где запись начинается.

    Запись в кавычках может занимать несколько строк; пустая строка даёт пустой список ячеек.
    """
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)
    records = []
    while True:
        start = reader.line_num + 1
        try:
            cells = next(reader)
        except StopIteration:
            return records
        records.append((start, cells))


def _is_junk(cells: list[str]) -> bool:
    """Строка из пустых ячеек, пробелов или одних разделителей."""
    return not any(cell.strip() for cell in cells)


def _column_index(header: list[str]) -> dict[str, int]:
    columns: dict[str, int] = {}
    for idx, name in enumerate(header):
        columns.setdefault(name.strip().casefold(), idx)
    return columns


def _layout(text: str, fmt_name: str | None) -> _Layout:
    if fmt_name is not None and fmt_name not in _FORMATS:
        raise UnknownFormatError(f"unknown format {fmt_name!r}")
    formats = [_FORMATS[fmt_name]] if fmt_name is not None else list(_FORMATS.values())

    headers: dict[str, tuple[int, list[str]]] = {}
    for delimiter in _DELIMITERS:
        header = next((rec for rec in _read_records(text, delimiter) if not _is_junk(rec[1])), None)
        if header is not None:
            headers[delimiter] = header
    if not headers:
        raise UnknownFormatError("file has no header line")

    matches = []
    for fmt in formats:
        if fmt.delimiter not in headers:
            continue
        line_no, cells = headers[fmt.delimiter]
        columns = _column_index(cells)
        if set(fmt.columns) <= columns.keys():
            matches.append((fmt, line_no, columns, cells))
    if len(matches) != 1:
        if fmt_name is not None:
            reason = f"header does not match format {fmt_name!r}"
        elif matches:
            names = ", ".join(m[0].name for m in matches)
            reason = f"header matches several formats: {names}"
        else:
            reason = "header matches no known format"
        raise UnknownFormatError(reason, line_no=1)

    fmt, header_line, columns, cells = matches[0]
    rows = [rec for rec in _read_records(text, fmt.delimiter) if rec[0] > header_line]
    return _Layout(format=fmt, columns=columns, width=len(cells), rows=rows)


def _parse_row(layout: _Layout, cells: list[str], imported_at: dt.datetime) -> Transaction:
    fmt = layout.format
    needed = max(layout.columns[col] for col in fmt.columns)
    if len(cells) <= needed:
        raise ValidationError("not enough fields")
    if len(cells) > layout.width and any(cell.strip() for cell in cells[layout.width :]):
        raise ValidationError("too many fields")
    values = {col: cells[layout.columns[col]].strip() for col in fmt.columns}
    date, amount, description = fmt.parse(values)
    return Transaction(date=date, amount=amount, description=description, imported_at=imported_at)


def _key(tx: Transaction) -> tuple[dt.date, Decimal, str]:
    return (tx.date, tx.amount, normalize_description(tx.description))


def detect_format(path: str | os.PathLike[str]) -> str:
    """Имя формата выписки (`nova`, `sfera`, `sfera_split`) по заголовку файла."""
    text, _ = _read_text(path)
    return _layout(text, None).format.name


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store.

    Нестрогий режим: плохие строки попадают в `errors`, остальные импортируются.
    Строгий режим: на первой плохой строке (в порядке файла) бросается StatementRowError,
    и store не меняется. Дубликаты (уже есть в store) ошибками не считаются.
    Все новые транзакции пишутся одним вызовом `store.add_many`.
    """
    clock = clock or SystemClock()
    imported_at = clock.now()
    text, encoding = _read_text(path)
    layout = _layout(text, fmt)

    # Дедупликация по количеству: k — сколько таких операций уже в хранилище.
    existing = Counter(_key(tx) for tx in store.all())
    new_txs: list[Transaction] = []
    errors: list[RowError] = []
    duplicates = 0
    for line_no, cells in layout.rows:
        if _is_junk(cells):
            continue
        try:
            tx = _parse_row(layout, cells, imported_at)
        except ValidationError as exc:
            if strict:
                raise StatementRowError(str(exc), line_no=line_no) from exc
            errors.append(RowError(line_no=line_no, message=str(exc)))
            continue
        key = _key(tx)
        if existing[key] > 0:
            existing[key] -= 1
            duplicates += 1
            continue
        if categorizer is not None:
            category = categorizer.categorize(tx)
            if category is not None:
                tx = Transaction(
                    date=tx.date,
                    amount=tx.amount,
                    description=tx.description,
                    category=category,
                    imported_at=tx.imported_at,
                )
        new_txs.append(tx)

    if new_txs:
        store.add_many(new_txs)
    logger.info("imported %d transactions from %s", len(new_txs), path)
    return ImportResult(
        format=layout.format.name,
        encoding=encoding,
        added=len(new_txs),
        duplicates=duplicates,
        errors=tuple(errors),
    )


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Импортирует выписку «Новы» в store и возвращает число добавленных транзакций."""
    result = import_statement(
        path, store, fmt="nova", strict=True, categorizer=categorizer, clock=clock
    )
    return result.added

